export const COUNT=12,OFFSETS=[-.8,.4,0,.8,-.4,.2,-.6,.6,-.2,1,-1,.3];
export function create(){return{network:'groups',seeds:[0,1],benefit:2,coordination:8,switching:1.5,bridge:false,compatibility:0,hold:true};}
export function validate(s){if(!s||!Array.isArray(s.seeds)||new Set(s.seeds).size!==s.seeds.length||s.seeds.some(x=>!Number.isInteger(x)||x<0||x>=COUNT)||typeof s.bridge!=='boolean'||typeof s.hold!=='boolean'||!Number.isFinite(s.benefit)||s.benefit<0||s.benefit>12||!Number.isFinite(s.coordination)||s.coordination<0||s.coordination>12||!Number.isFinite(s.switching)||s.switching<0||s.switching>6||!Number.isFinite(s.compatibility)||s.compatibility<0||s.compatibility>1)throw Error('Invalid adoption assumptions');const network=s.network||'groups';if(!['groups','mixed','hub','custom'].includes(network))throw Error('Unknown network');if(network!=='groups'&&s.bridge)throw Error('Preset bridges apply only to the two groups');if(network==='custom'){if(s.layout!==undefined&&!['groups','mixed','hub'].includes(s.layout))throw Error('Unknown network layout');if(!Array.isArray(s.links)||s.links.length>66)throw Error('Invalid connections');const seen=new Set();for(const pair of s.links){if(!Array.isArray(pair)||pair.length!==2||pair.some(x=>!Number.isInteger(x)||x<0||x>=COUNT)||pair[0]===pair[1])throw Error('Invalid connection');const key=[...pair].sort((a,b)=>a-b).join('-');if(seen.has(key))throw Error('Duplicate connection');seen.add(key);}}return s;}
export function edges(s){const network=s.network||'groups';if(network==='custom')return s.links.map(([a,b])=>a<b?[a,b]:[b,a]).sort((a,b)=>a[0]-b[0]||a[1]-b[1]);if(network==='hub')return Array.from({length:11},(_,i)=>[0,i+1]);const out=[];for(let i=0;i<COUNT;i++)for(let j=i+1;j<COUNT;j++){const d=j-i;if(network==='mixed'?[1,2,6,10,11].includes(d):Math.floor(i/6)===Math.floor(j/6))out.push([i,j]);}if(network==='groups'&&s.bridge)out.push([2,6],[5,9]);return out;}
export function initial(s){validate(s);return Array.from({length:12},(_,i)=>s.seeds.includes(i));}
export function assess(s,adopted){const links=edges(s);return adopted.map((current,i)=>{const neighbours=links.flatMap(([a,b])=>a===i?[b]:b===i?[a]:[]),share=neighbours.length?neighbours.filter(j=>adopted[j]).length/neighbours.length:0,coordination=neighbours.length?s.coordination:0,personal=s.benefit+OFFSETS[i],newValue=personal+coordination*(share+s.compatibility*(1-share)),oldValue=coordination*(1-share),gain=newValue-oldValue,held=s.hold&&s.seeds.includes(i),next=held?true:current?(gain < -s.switching?false:true):gain>s.switching;return{current,next,neighbours,share,personal,newValue,oldValue,gain,held};});}
export function simulate(s,limit=24){validate(s);const history=[initial(s)],seen=new Map([[history[0].join(','),0]]);let status='limit reached',cycleStart=null,cycleLength=null;for(let t=1;t<=limit;t++){const next=assess(s,history.at(-1)).map(x=>x.next);history.push(next);if(next.every((x,i)=>x===history.at(-2)[i])){status='stable';break;}const key=next.join(',');if(seen.has(key)){status='cycle';cycleStart=seen.get(key);cycleLength=t-cycleStart;break;}seen.set(key,t);}return{history,status,final:history.at(-1),rounds:history.length-1,cycleStart,cycleLength};}
export function stateAt(result,round){if(round<result.history.length)return result.history[round];if(result.status==='cycle')return result.history[result.cycleStart+(round-result.cycleStart)%result.cycleLength];return result.final;}
